arguments.command:
pwd && node -e "
var j = JSON.parse(require('fs').readFileSync('outputs/pr_review.json','utf8'));
console.log('JSON valid. recommendation=' + j.recommendation);
console.log('issueCounts=' + JSON.stringify(j.issueCounts));
console.log('inlineComments=' + j.inlineComments.length);
j.inlineComments.forEach(function(c){
  var fs=require('fs');
  if (!fs.existsSync(c.comment)) { console.log('MISSING comment file: '+c.comment); process.exit(1); }
  var body = fs.readFileSync(c.comment,'utf8');
  if (c.severity==='IMPORTANT' && body.indexOf('⚠️ **IMPORTANT')!==0) { console.log('severity marker mismatch in '+c.comment); process.exit(1); }
  if (c.severity==='SUGGESTION' && body.indexOf('💡 **SUGGESTION')!==0) { console.log('severity marker mismatch in '+c.comment); process.exit(1); }
  if (c.severity==='NIT' && body.indexOf('🪶 **NIT')!==0) { console.log('severity marker mismatch in '+c.comment); process.exit(1); }
  console.log('OK ' + c.path + ':' + c.line + ' -> ' + c.comment + ' [' + c.severity + ']');
});
console.log('no response.md written: ' + (!require('fs').existsSync('outputs/response.md')));
"

